begin;
do $$
declare a uuid;b uuid;c uuid; old_room uuid;old_code text;new_room uuid;nonce uuid:=gen_random_uuid();inv uuid:=gen_random_uuid();second_inv uuid:=gen_random_uuid();raw jsonb;denied boolean;
begin
 select f.user_id,f.friend_id into a,b from public.friends f where f.user_id<>f.friend_id and exists(select 1 from public.friends g where g.user_id=f.friend_id and g.friend_id=f.user_id) limit 1;
 select id into c from auth.users where id not in(a,b) limit 1;
 if a is null or c is null then raise exception 'Need friend pair and third account';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);execute 'set local role authenticated';
 raw:=public.group_ui_action('fresh',jsonb_build_object('replace',true,'request_id',gen_random_uuid()));old_room:=(raw->'room'->>'id')::uuid;old_code:=raw->'room'->>'code';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 perform public.group_room_action('join',old_code,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 raw:=public.group_ui_action('fresh',jsonb_build_object('replace',true,'room_id',old_room,'request_id',nonce));new_room:=(raw->'room'->>'id')::uuid;
 assert new_room<>old_room,'fresh room is genuinely new';assert jsonb_array_length(raw->'room'->'members')=1,'old participants not carried over';
 raw:=public.group_ui_action('fresh',jsonb_build_object('replace',true,'room_id',old_room,'request_id',nonce));assert raw->'room'->>'id'=new_room::text,'retry same request returns same room';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 raw:=public.group_ui_snapshot();assert raw->'room'->>'id'=old_room::text and raw->'room'->>'host_id'=b::text,'previous peers keep their room and leadership';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 perform public.group_room_action('join',old_code,true);
 update public.group_rides_members set workout_state='active' where group_id=old_room and user_id=c;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 perform public.group_ui_action('invite',jsonb_build_object('receiver_id',b,'id',inv));
 raw:=public.group_ui_action('view',jsonb_build_object('id',inv));assert raw->>'status'='active','sender membership does not mean recipient acceptance';
 raw:=public.group_ui_snapshot();assert jsonb_array_length(raw->'room'->'members')=1,'sending does not add participant';
 assert exists(select 1 from jsonb_array_elements(raw->'invitations') x where x->>'id'=inv::text and x->>'status'='pending');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 denied:=false;begin perform public.group_ui_action('accept',jsonb_build_object('id',inv));exception when others then denied:=true;end;assert denied,'outsider cannot accept';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 perform public.group_ui_action('decline',jsonb_build_object('id',inv));
 denied:=false;begin perform public.group_invite_action(inv,'accept',true);exception when others then denied:=true;end;assert denied,'decline enforced for previous API too';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 perform public.group_ui_action('invite',jsonb_build_object('receiver_id',b,'id',second_inv));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 raw:=public.group_ui_action('accept',jsonb_build_object('id',second_inv,'replace',true));assert raw->>'status'='joined';
 raw:=public.group_ui_snapshot();assert jsonb_array_length(raw->'room'->'members')=2;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 raw:=public.group_ui_snapshot();assert raw->'room'->>'id'=old_room::text and raw->'room'->>'host_id'=c::text,'accepting another invitation preserves remaining peers';
 assert exists(select 1 from jsonb_array_elements(raw->'room'->'members') x where x->>'user_id'=c::text and x->>'workout_state'='active'),'peer recording state continues';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 denied:=false;begin perform public.group_ui_action('invite',jsonb_build_object('receiver_id',b,'id',gen_random_uuid()));exception when others then denied:=sqlerrm like '%ALREADY_JOINED%';end;assert denied;
 raw:=public.group_ui_action('depart',jsonb_build_object('room_id',new_room));assert raw->'room'='null'::jsonb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 raw:=public.group_ui_snapshot();assert raw->'room'->>'id'=new_room::text and raw->'room'->>'host_id'=b::text,'personal finish preserves others';
 perform public.group_ui_action('depart',jsonb_build_object('room_id',new_room));
 execute 'reset role';
 assert (select count(*) from public.group_rides_members where group_id=new_room)=2,'member result rows retained';
 assert (select closed_at is not null from public.group_rides where id=new_room),'last departure closes ride';
 assert not has_function_privilege('anon','public.group_ui_action(text,jsonb)','execute');
end $$;
rollback;
select 'Group fresh identity, idempotency, explicit acceptance/decline, outsider denial, safe host departure and retained results passed; rolled back' result;
